class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        // ① 算法核心思路：从最低位起逐位相加并记录进位，结果按位生成新节点
        // ② 关键步骤与易错点：循环条件 l1 || l2 || carry 处理不等长与最高位进位；用 long long 累加避免溢出
        // ③ 时间复杂度 O(max(n1, n2))，空间复杂度 O(max(n1, n2))（结果链）
        // 逐位相加并处理进位；用 long long 累加避免溢出
        ListNode dummy(0);
        ListNode* cur = &dummy;
        long long carry = 0;
        while (l1 || l2 || carry) {
            long long s = carry;
            if (l1) { s += l1->val; l1 = l1->next; }
            if (l2) { s += l2->val; l2 = l2->next; }
            cur->next = new ListNode((int)(s % 10));
            cur = cur->next;
            carry = s / 10;
        }
        return dummy.next;
    }
};

