    ListNode(int x = 0) : val(x), next(nullptr) {}
};

int main() {
    // ① 算法核心思路：快慢指针找中点，反转后半段后逐节点比较判回文
    // ② 关键步骤与易错点：先读 n 再读节点值；比较以 right 非空为终止条件
    // ③ 时间复杂度 O(n)，空间复杂度 O(n)（构建链表）
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    ListNode* head = new ListNode();
    ListNode* cur = head;
    for (int i = 0; i < n; i++) {
        int v;
        cin >> v;
        cur->next = new ListNode(v);
        cur = cur->next;
    }
    head = head->next;

    ListNode* slow = head;
    ListNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    ListNode* prev = nullptr;
    while (slow) {
        ListNode* nxt = slow->next;
        slow->next = prev;
        prev = slow;
        slow = nxt;
    }
    ListNode* left = head;
    ListNode* right = prev;
    bool ok = true;
    while (right) {
        if (left->val != right->val) { ok = false; break; }
        left = left->next;
        right = right->next;
    }
    cout << (ok ? "true" : "false") << '\n';
    return 0;
}

